    intro: 'ஃபார்வர்டுகள், பதிவுகள், தலைப்புச் செய்திகள், வீடியோக்களைப் படித்து எது நம்பகமானது, எது போலி, எதை முதலில் சரிபார்க்க வேண்டும் என்று முடிவு செய்யுங்கள்; ஒவ்வொன்றின் ஆபத்து அறிகுறிகளையும், தீர்வு தரும் ஒரே ஒரு சோதனையையும் கற்றுக்கொள்ளுங்கள்.',
