    start_desc: 'இந்தியத் தொலைபேசிகளுக்கு தினமும் வரும் வகையான 12 செய்திகள்: WhatsApp ஃபார்வர்டுகள், பதிவுகள், தலைப்புகள், வீடியோக்கள், ஸ்கிரீன்ஷாட்கள். சில உண்மை, பல அல்ல, சிலவற்றை சரிபார்க்காமல் நம்ப முடியாது. முடிவு செய்யுங்கள், பிறகு ஆபத்து அறிகுறிகளையும் தீர்வு தரும் சோதனையையும் பாருங்கள்.',
