    chk_desc: 'இந்தச் சோதனைக் கருவி தவறாக வழிநடத்தும் ஃபார்வர்டுகளில் பொதுவான அமைப்புகளைத் தேடுகிறது. இது மனதைப் படிக்காது: அறிகுறி இல்லாத செய்தியும் பொய்யாக இருக்கலாம்; உண்மையான செய்தியும் மோசமாக எழுதப்பட்டிருக்கலாம்.',
    chk_label: 'செய்தி உரை',
    chk_ph: 'WhatsApp ஃபார்வர்டு, SMS அல்லது பதிவை இங்கே ஒட்டுங்கள்…',
    chk_examples: 'அல்லது ஒரு எடுத்துக்காட்டை முயற்சிக்கவும்:',
    ex_scam_btn: 'சந்தேகத்திற்குரிய ஃபார்வர்டு',
    ex_calm_btn: 'அமைதியான செய்தி',
    ex_bank_btn: 'வங்கி பாணி SMS',
    ex_scam: 'அவசரம்!!! அரசு ஒவ்வொரு மாணவருக்கும் இலவச லேப்டாப் வழங்குகிறது. இன்று மட்டும்! இங்கே பதிவு செய்யுங்கள்: free-laptop-gov-in.top மேலும் 10 பேருக்கு ஃபார்வர்டு செய்யுங்கள், இல்லையெனில் சலுகை ரத்து. 100% உண்மை.',
    ex_calm: 'அன்புள்ள பெற்றோர்களே, 8 ஆம் வகுப்பு பெற்றோர்-ஆசிரியர் கூட்டம் சனிக்கிழமை 18 அக்டோபர், காலை 9 முதல் மதியம் 12 வரை பள்ளி அரங்கில் நடைபெறும். அறிக்கை அட்டையைக் கொண்டு வரவும். — தலைமை ஆசிரியர், சன்ரைஸ் பப்ளிக் பள்ளி',
    ex_bank: 'அன்புள்ள வாடிக்கையாளரே, உங்கள் கணக்கு 24 மணி நேரத்தில் முடக்கப்படும். உடனே bankofkaveri-kyc.com இல் KYC புதுப்பித்து, சரிபார்க்கப் பெறும் OTP ஐப் பகிரவும்.',
    chk_result: 'முடிவு',
    chk_empty: 'ஆபத்து அறிகுறிகளைக் காண ஒரு செய்தியை ஒட்டுங்கள் அல்லது தட்டச்சு செய்யுங்கள்.',
    lvl_low: 'பொதுவான ஆபத்து அறிகுறிகள் இல்லை',
    lvl_medium: 'கவனமாக இருங்கள்',
    lvl_high: 'மிகுந்த எச்சரிக்கை',
    lvl_low_d: 'எங்கள் தந்திரப் பட்டியலில் எதுவும் இங்கே பொருந்தவில்லை. அதனால் அது உண்மையாகிவிடாது: இன்னும் யார், எப்போது, எங்கே, என்ன ஆதாரம் என்று கேளுங்கள்.',
    lvl_medium_d: 'சில எச்சரிக்கை அறிகுறிகள். 5 கேள்விகளால் சரிபார்க்கும் வரை ஃபார்வர்டு செய்யாதீர்கள்.',
    lvl_high_d: 'பல எச்சரிக்கை அறிகுறிகள். ஃபார்வர்டு செய்யாதீர்கள். ஒரு வார்த்தையை நம்பும் முன் அதிகாரப்பூர்வ ஆதாரத்தைச் சரிபாருங்கள்.',
    chk_flags_n: '{n} ஆபத்து அறிகுறிகள் கண்டறியப்பட்டன',
    chk_flags_1: '1 ஆபத்து அறிகுறி கண்டறியப்பட்டது',
    chk_flags_0: 'ஆபத்து அறிகுறிகள் எதுவும் இல்லை',
