    chk_text_title: 'ஆபத்து அறிகுறிகள் குறிக்கப்பட்ட உங்கள் செய்தி',
    chk_stats: '{w} சொற்கள் · {c}% பெரிய எழுத்துகள் · {e} ஆச்சரியக்குறிகள் · {l} இணைப்புகள்',
    chk_disclaimer: 'இது ஒரு அமைப்புச் சோதனை மட்டுமே. ஒரு செய்தி உண்மையா என்பதை சரிபார்ப்பு (5 கேள்விகள், அதிகாரப்பூர்வ ஆதாரம், உண்மைச் சரிபார்ப்புத் தளம்) மட்டுமே முடிவு செய்யும்.',
