    cf_caps: 'பெரிய எழுத்துகளில் கத்துதல்',
    cfd_caps: 'பல சொற்கள் பெரிய எழுத்துகளில்: தகவலுக்குப் பதில் உணர்ச்சி.',
    cf_exclaim: 'பல !!! அல்லது ???',
    cfd_exclaim: 'வரிசையான ஆச்சரியக்குறிகள் நாடகத்தின் அறிகுறி, உண்மையின் அல்ல.',
    cf_shortlink: 'சுருக்கப்பட்ட இணைப்பு',
    cfd_shortlink: 'bit.ly, tinyurl போன்ற இணைப்புகள் உண்மையில் எங்கே செல்கின்றன என்பதை மறைக்கின்றன.',
    cf_lookalike: 'சந்தேகத்திற்குரிய இணைய முகவரி',
    cfd_lookalike: 'முகவரி அறியப்பட்ட பெயரைப் பிரதி எடுக்கிறது, விசித்திரமான முடிவைப் பயன்படுத்துகிறது, அல்லது நேர்மையான தளங்கள் தவிர்க்கும் "kyc", "gift", "gov" போன்ற சொற்களைக் கொண்டுள்ளது.',
    cf_money: 'பணம் அல்லது கட்டணம் கேட்கிறது',
    cfd_money: 'ஏதாவது கிடைக்கும் முன் கட்டணம், வைப்பு, ரீசார்ஜ் அல்லது "KYC புதுப்பிப்பு".',
