    fc_factly_d: 'సరళ భాషలో ఫ్యాక్ట్ చెక్‌లు, ప్రభుత్వ డేటా వివరణలు.',
    fc_vishvas_d: 'ఒక హిందీ వార్తాపత్రిక గ్రూపు ఫ్యాక్ట్-చెక్ బృందం, పలు భారతీయ భాషల్లో.',
    fc_quint_d: 'వైరల్ వార్తలు, వీడియోల కోసం ఒక న్యూస్ సైట్ ఫ్యాక్ట్-చెక్ డెస్క్.',
    help_title: 'సైబర్ నేరమా? సహాయం పొందండి',
    help_1930: '1930కి ఫోన్ చేయండి (జాతీయ సైబర్ క్రైమ్ హెల్ప్‌లైన్) లేదా cybercrime.gov.in లో ఫిర్యాదు చేయండి.',
    help_note: 'నకిలీ లింకు లేదా OTP కాల్‌తో డబ్బు పోయిందా? వెంటనే 1930కి ఫోన్ చేయండి: మొదటి కొన్ని గంటల్లో ఫిర్యాదు చేస్తే బదిలీని ఆపే అవకాశం ఎక్కువ.',
    fwd_title: '"చాలాసార్లు ఫార్వర్డ్ చేయబడింది" అంటే ఏమిటి',
    fwd_d1: 'పంపినవారు సందేశం రాయకపోతే WhatsApp "ఫార్వర్డ్ చేయబడింది" (ఒక బాణం) జోడిస్తుంది; అది ఐదు లేదా అంతకన్నా ఎక్కువ చాట్‌ల గొలుసు దాటి వస్తే "చాలాసార్లు ఫార్వర్డ్ చేయబడింది" (రెండు బాణాలు).',
    fwd_d2: 'అలాంటి సందేశాన్ని ఒకసారి ఒకే చాట్‌కు ఫార్వర్డ్ చేయగలం: WhatsApp స్వయంగా దాని వేగం తగ్గించే ప్రయత్నం చేస్తోంది.',
    fwd_d3: 'ఈ లేబుల్ సందేశం అబద్ధమని చెప్పదు. ఇది చెప్పేది: ఈ గొలుసులో ఎవరూ దీన్ని రాయలేదు, ఎవరు రాశారో ఎవరికీ తెలియదు. సరిచూసే వరకు దీన్ని ధృవీకరించనిదిగా భావించండి.',
    oops_title: 'ఇప్పటికే అబద్ధమైనది ఫార్వర్డ్ చేశారా?',
    oops_d: 'అందరికీ జరుగుతుంది. అదే గ్రూపులో సవరణ పంపండి ("క్షమించండి, ఇది అబద్ధమని తేలింది, ఈ ఫ్యాక్ట్ చెక్ చూడండి"), సందేశాన్ని అందరికీ తొలగించండి, మీకు పంపినవారికి చెప్పండి.',
    class_title: 'క్లాస్ మోడ్: తరగతి మొత్తం నిర్ణయిస్తుంది',
    class_desc: 'ప్రొజెక్టర్‌పై ఒకసారి ఒక సందేశం చూపించండి. విద్యార్థులు చేతులెత్తి ఓటు వేస్తారు: నమ్మదగినది, నకిలీ లేదా ముందు సరిచూడండి. చేతులు లెక్కించి, బయటపెట్టు నొక్కి, ప్రమాద సంకేతాలు చర్చించి, తదుపరి సందేశానికి వెళ్లండి.',
