    class_novote: 'ఓట్లు లెక్కించలేదు. సమాధానం:',
    ws_title: 'ముద్రించగల వర్క్‌షీట్',
    ws_desc: 'ఎంచుకున్న స్థాయి నుంచి 8 సందేశాలు టిక్ బాక్సులతో, ఉపాధ్యాయుల కోసం వేరే పేజీలో జవాబుల కీ.',
