    ws_sheet_title: 'వర్క్‌షీట్: ఫేక్ న్యూస్ డిటెక్టివ్',
    ws_name: 'పేరు: ____________________   తరగతి: ________   తేదీ: __________',
    ws_instr: 'ప్రతి సందేశం చదవండి. నమ్మదగినది, నకిలీ లేదా ముందు సరిచూడండి అని టిక్ చేయండి. తర్వాత మీరు గమనించిన ఒక ప్రమాద సంకేతం, తేల్చే ఒక తనిఖీ రాయండి.',
