    ris_p3: 'ಗ್ಯಾಲರಿಯಿಂದ ಉಳಿಸಿದ ಚಿತ್ರ ಆಯ್ಕೆಮಾಡಿ.',
    ris_p4: 'ಶಾಪಿಂಗ್ ಫಲಿತಾಂಶಗಳನ್ನು ದಾಟಿ ಅದೇ ಚಿತ್ರ ತೋರಿಸುವ ಪುಟಗಳಿಗೆ ಹೋಗಿ. ಅತ್ಯಂತ ಹಳೆಯ ದಿನಾಂಕ ಮತ್ತು ನಂಬಲರ್ಹ ಸೈಟ್ ಹುಡುಕಿ: ಫೋಟೋ ನಿಜವಾಗಿ ಎಲ್ಲಿಂದ ಬಂತು ಎಂದು ಅದು ಹೇಳುತ್ತದೆ.',
