    fc_alt_d: 'ಸ್ವತಂತ್ರ ಫ್ಯಾಕ್ಟ್-ಚೆಕಿಂಗ್ ಸೈಟ್, ಇಂಗ್ಲಿಷ್ ಮತ್ತು ಹಿಂದಿಯಲ್ಲಿ.',
    fc_boom_d: 'ಸ್ವತಂತ್ರ ಫ್ಯಾಕ್ಟ್-ಚೆಕಿಂಗ್ ನ್ಯೂಸ್‌ರೂಂ, ಹಲವು ಭಾಷೆಗಳಲ್ಲಿ.',
