    fc_vishvas_d: 'ಒಂದು ಹಿಂದಿ ಪತ್ರಿಕಾ ಸಮೂಹದ ಫ್ಯಾಕ್ಟ್-ಚೆಕ್ ತಂಡ, ಹಲವು ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ.',
