    help_title: 'ಸೈಬರ್ ಅಪರಾಧವೇ? ಸಹಾಯ ಪಡೆಯಿರಿ',
    help_1930: '1930 ಗೆ ಕರೆ ಮಾಡಿ (ರಾಷ್ಟ್ರೀಯ ಸೈಬರ್ ಅಪರಾಧ ಸಹಾಯವಾಣಿ) ಅಥವಾ cybercrime.gov.in ನಲ್ಲಿ ದೂರು ನೀಡಿ.',
    help_note: 'ನಕಲಿ ಲಿಂಕ್ ಅಥವಾ OTP ಕರೆಯಿಂದ ಹಣ ಕಳೆದುಕೊಂಡಿರಾ? ತಕ್ಷಣ 1930 ಗೆ ಕರೆ ಮಾಡಿ: ಮೊದಲ ಕೆಲವು ಗಂಟೆಗಳಲ್ಲಿ ದೂರು ನೀಡಿದರೆ ವರ್ಗಾವಣೆ ತಡೆಯುವ ಉತ್ತಮ ಅವಕಾಶ.',
    fwd_title: '"ಹಲವು ಬಾರಿ ಫಾರ್ವರ್ಡ್ ಆಗಿದೆ" ಎಂದರೇನು',
    fwd_d1: 'ಕಳುಹಿಸಿದವರು ಸಂದೇಶ ಬರೆಯದಿದ್ದರೆ WhatsApp "ಫಾರ್ವರ್ಡ್ ಆಗಿದೆ" (ಒಂದು ಬಾಣ) ಸೇರಿಸುತ್ತದೆ; ಐದು ಅಥವಾ ಹೆಚ್ಚು ಚಾಟ್‌ಗಳ ಸರಪಳಿ ದಾಟಿ ಬಂದರೆ "ಹಲವು ಬಾರಿ ಫಾರ್ವರ್ಡ್ ಆಗಿದೆ" (ಎರಡು ಬಾಣ).',
    fwd_d2: 'ಅಂತಹ ಸಂದೇಶವನ್ನು ಒಮ್ಮೆಗೆ ಒಂದೇ ಚಾಟ್‌ಗೆ ಫಾರ್ವರ್ಡ್ ಮಾಡಬಹುದು: WhatsApp ತಾನೇ ಅದರ ವೇಗ ತಗ್ಗಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತಿದೆ.',
    fwd_d3: 'ಈ ಲೇಬಲ್ ಸಂದೇಶ ಸುಳ್ಳು ಎಂದು ಹೇಳುವುದಿಲ್ಲ. ಅದು ಹೇಳುವುದು: ಈ ಸರಪಳಿಯಲ್ಲಿ ಯಾರೂ ಇದನ್ನು ಬರೆದಿಲ್ಲ, ಯಾರು ಬರೆದರೆಂದು ಯಾರಿಗೂ ಗೊತ್ತಿಲ್ಲ. ಪರಿಶೀಲಿಸುವವರೆಗೆ ಇದನ್ನು ಅಪರಿಶೀಲಿತವೆಂದು ಪರಿಗಣಿಸಿ.',
    oops_title: 'ಈಗಾಗಲೇ ಸುಳ್ಳನ್ನು ಫಾರ್ವರ್ಡ್ ಮಾಡಿದ್ದೀರಾ?',
    oops_d: 'ಎಲ್ಲರಿಗೂ ಆಗುತ್ತದೆ. ಅದೇ ಗುಂಪಿನಲ್ಲಿ ತಿದ್ದುಪಡಿ ಕಳುಹಿಸಿ ("ಕ್ಷಮಿಸಿ, ಇದು ಸುಳ್ಳೆಂದು ತಿಳಿಯಿತು, ಈ ಫ್ಯಾಕ್ಟ್ ಚೆಕ್ ನೋಡಿ"), ಎಲ್ಲರಿಗೂ ಸಂದೇಶ ಅಳಿಸಿ, ನಿಮಗೆ ಕಳುಹಿಸಿದವರಿಗೆ ತಿಳಿಸಿ.',
    class_title: 'ತರಗತಿ ಮೋಡ್: ಇಡೀ ತರಗತಿ ನಿರ್ಧರಿಸುತ್ತದೆ',
    class_desc: 'ಪ್ರೊಜೆಕ್ಟರ್‌ನಲ್ಲಿ ಒಮ್ಮೆಗೆ ಒಂದು ಸಂದೇಶ ತೋರಿಸಿ. ವಿದ್ಯಾರ್ಥಿಗಳು ಕೈ ಎತ್ತಿ ಮತ ಹಾಕುತ್ತಾರೆ: ನಂಬಲರ್ಹ, ನಕಲಿ ಅಥವಾ ಮೊದಲು ಪರಿಶೀಲಿಸಿ. ಕೈಗಳನ್ನು ಎಣಿಸಿ, ಬಹಿರಂಗಪಡಿಸಿ ಒತ್ತಿ, ಅಪಾಯದ ಸೂಚನೆಗಳನ್ನು ಚರ್ಚಿಸಿ, ಮುಂದಿನ ಸಂದೇಶಕ್ಕೆ ಹೋಗಿ.',
