    w_satire: 'ವಿಡಂಬನೆ',
    w_satire_d: 'ಸುದ್ದಿ ರೂಪದಲ್ಲಿ ಬರೆದ ಹಾಸ್ಯ. ತನ್ನ ಸೈಟ್‌ನಲ್ಲಿ ನಿರುಪದ್ರವಿ, ನಿಜವೆಂದು ಫಾರ್ವರ್ಡ್ ಮಾಡಿದರೆ ದಾರಿತಪ್ಪಿಸುವ.',
    w_deepfake: 'ಡೀಪ್‌ಫೇಕ್',
    w_deepfake_d: 'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಎಂದೂ ಹೇಳದ್ದನ್ನು ಅಥವಾ ಮಾಡದ್ದನ್ನು ಹೇಳಿದಂತೆ ಅಥವಾ ಮಾಡಿದಂತೆ ತೋರಿಸಲು AI ಸೃಷ್ಟಿಸಿದ ಅಥವಾ ಬದಲಿಸಿದ ವೀಡಿಯೊ, ಫೋಟೋ ಅಥವಾ ಧ್ವನಿ.',
    w_factcheck: 'ಫ್ಯಾಕ್ಟ್ ಚೆಕ್',
    w_factcheck_d: 'ವೈರಲ್ ಹೇಳಿಕೆಯನ್ನು ಪುರಾವೆಗಳೊಂದಿಗೆ ಪರೀಕ್ಷಿಸಿ ನಿಜ, ಸುಳ್ಳು ಅಥವಾ ದಾರಿತಪ್ಪಿಸುವ ಎಂದು ಹೇಳುವ ವರದಿ.',
    w_source: 'ಮೂಲ',
    w_source_d: 'ಮಾಹಿತಿ ಯಾವ ವ್ಯಕ್ತಿ ಅಥವಾ ಸಂಸ್ಥೆಯಿಂದ ಬರುತ್ತದೋ ಅದು. ಮೂಲವಿಲ್ಲ, ನಂಬಿಕೆಯಿಲ್ಲ.',
    w_clickbait: 'ಕ್ಲಿಕ್‌ಬೇಟ್',
    w_clickbait_d: 'ನೀವು ಒತ್ತುವಂತೆ ಬರೆದ ಹೆಡ್‌ಲೈನ್ ("ನೀವು ನಂಬುವುದಿಲ್ಲ…"), ತಿಳಿಸಲು ಅಲ್ಲ.',
    howto_title: 'ಬಳಸುವುದು ಹೇಗೆ / ತರಗತಿಗೆ ಆಲೋಚನೆಗಳು',
    tip1: 'ಆಟ: ಹಂತ ಆಯ್ಕೆಮಾಡಿ, ಪ್ರತಿ ಸಂದೇಶವನ್ನು ನಿಮ್ಮ ಫೋನ್‌ಗೆ ಬಂದಂತೆ ಓದಿ, ನಿರ್ಧರಿಸಿ, ನಂತರ ಅಪಾಯದ ಸೂಚನೆಗಳನ್ನು ಮತ್ತು ತೀರ್ಮಾನಿಸುವ ಪರಿಶೀಲನೆಯನ್ನು ಓದಿ.',
    tip2: 'ಸಂದೇಶ ಪರೀಕ್ಷೆ: ನಿಮಗೆ ಬಂದ ಯಾವುದೇ ನಿಜವಾದ ಫಾರ್ವರ್ಡ್ ಅಂಟಿಸಿ. ಪಠ್ಯದಲ್ಲಿ ಅಪಾಯದ ಸೂಚನೆಗಳನ್ನು ಗುರುತಿಸಲಾಗುತ್ತದೆ; ಎಚ್ಚರಿಕೆಯ ಮಟ್ಟ ಎಷ್ಟು ಜಾಗರೂಕವಾಗಿ ಪರಿಶೀಲಿಸಬೇಕೆಂದು ಹೇಳುತ್ತದೆ.',
    tip3: 'ತರಗತಿ ಚಟುವಟಿಕೆ: ತರಗತಿ ಮೋಡ್‌ನಲ್ಲಿ ಪ್ರೊಜೆಕ್ಟರ್‌ನಲ್ಲಿ ಒಂದು ಸಂದೇಶ ತೋರಿಸಿ. ತರಗತಿ ಕೈ ಎತ್ತಿ ಮತ ಹಾಕುತ್ತದೆ, ನಂತರ ಒಬ್ಬ ವಿದ್ಯಾರ್ಥಿ ಯಾವ ಪರಿಶೀಲನೆ ತೀರ್ಮಾನಿಸುತ್ತದೆಂದು ವಿವರಿಸುತ್ತಾನೆ. ತರಗತಿ ಅಂಕ ದಾಖಲಿಸಿ.',
    tip4: 'ಮನೆಗೆಲಸ: ವರ್ಕ್‌ಶೀಟ್ ಮುದ್ರಿಸಿ. ವಿದ್ಯಾರ್ಥಿಗಳು ಉತ್ತರ ಟಿಕ್ ಮಾಡಿ ಪ್ರತಿ ಸಂದೇಶಕ್ಕೆ ಒಂದು ಅಪಾಯದ ಸೂಚನೆ ಮತ್ತು ಒಂದು ಪರಿಶೀಲನೆ ಬರೆಯುತ್ತಾರೆ; ಕೀ ಕೊನೆಯ ಪುಟದಲ್ಲಿದೆ.',
    tip5: 'ಯೋಜನೆ: ಪ್ರತಿ ಗುಂಪು ಒಂದು ನಿಜವಾದ ವೈರಲ್ ಸಂದೇಶ ತಂದು (ವೈಯಕ್ತಿಕ ದತ್ತಾಂಶವಿಲ್ಲದೆ), 5 ಪ್ರಶ್ನೆಗಳು ಮತ್ತು ರಿವರ್ಸ್ ಇಮೇಜ್ ಸರ್ಚ್ ಮಾಡಿ, ತೀರ್ಪು ಮಂಡಿಸುತ್ತದೆ.',
