    poster_r1: 'നിൽക്കൂ. ശക്തമായ വികാരങ്ങൾ (ദേഷ്യം, ഭയം, അഭിമാനം) സാവധാനമാകാനുള്ള സൂചനയാണ്.',
    poster_r2: '5 ചോദ്യങ്ങൾ ചോദിക്കൂ: ആര്, എപ്പോൾ, എവിടെ, എന്തിന്, എന്ത് തെളിവ്.',
    poster_r3: 'വെബ് വിലാസം അക്ഷരം അക്ഷരമായി വായിക്കൂ. ഔദ്യോഗിക വിലാസങ്ങൾ സ്വയം ടൈപ്പ് ചെയ്യൂ.',
    poster_r4: 'ചിത്രം തിരയൂ. പഴയ ഫോട്ടോകൾക്ക് ഓരോ വർഷവും പുതിയ കഥകൾ കിട്ടുന്നു.',
    poster_r5: 'ഒരു സമ്മാനത്തിനോ ജോലിക്കോ "പരിശോധന"യ്ക്കോ ഒരിക്കലും പണം നൽകരുത്, OTP പങ്കിടരുത്.',
    poster_r6: 'ഉറപ്പില്ലേ? ഫോർവേഡ് ചെയ്യരുത്. ഫാക്ട്-ചെക്ക് സൈറ്റിൽ ഒരു തിരച്ചിലിന് ഒരു മിനിറ്റ് മതി.',
